7	// Three gates (checked in order), plus the retired-namespace redirects:
8	//
9	// 1. /nomadik (RETIRED 2026-08-03) and /handymanclonakilty (RETIRED 2026-07-14):
10	//    the two legacy single-tenant gated docs, both migrated fully into the
11	//    /client portal, so each namespace now permanent-redirects to the portal
12	//    login pre-filled with the workspace. Kept as explicit redirects (not 404s)
13	//    so the founders' old bookmarks keep working.
14	//
15	// 2. /client gate (always on): the multi-tenant AEO client dashboard. A signed
16	//    cookie (sol_client) carries method 'client' plus one or more granted
17	//    slugs (an email-based sign-in allowlisted into several workspaces gets
18	//    all of them at once - no per-workspace pick). Passwords are verified
19	//    against the per-client repo config (content/clients/<slug>/config.ts,
20	//    authHash = sha256(CLIENT_AUTH_PEPPER + password)) - not a database, not
21	//    the VPS, and not a shared env password; see lib/client-auth.ts.
22	//    Onboarding a client is therefore a repo change and does need a deploy.
23	//    /client/admin is the owner-only surface nested inside it and is checked
24	//    FIRST, so a tenant session can never open it.
25	//
26	// 3. /lab gate (always on in a deployed build): the nine design-prototype
27	//    routes. They carry noindex, which stops Google indexing them but does
28	//    NOT stop the sixteen AI crawlers robots.txt names by allowing them - and
29	//    /lab/work-treatments states an unlaunched product name and its status.
30	//    Owner cookie only, same as /client/admin. Bypassed in development so
31	//    `npm run boards` can still load /lab/board/<slug> off a local dev server
32	//    to screenshot it.
33	//
34	// 3.5. /internal gate (always on): owner-only personal-tooling pages, same
35	//    cookie as /lab. Currently just /internal/ingest - the hosted summaries
36	//    from the personal email-ingest automation. /api/internal/* is exempt
37	//    from THIS gate because it authenticates with its own bearer token
38	//    (lib/internal-ingest/auth.ts): the automation is a headless script, not
39	//    a browser, so it has no owner cookie to present.
40	//
41	// 4. Site-wide pre-launch gate (DORMANT by default): with no SITE_GATE_PASSWORD
42	//    set this is a no-op. Turned on/off purely by adding/removing
43	//    SITE_GATE_PASSWORD in Vercel - no code change. While active it returns 401
44	//    to everyone, including crawlers; remove the env var to launch.
45	/** The workspace slug of the same-origin portal page a request came from
46	 *  (Referer /client/<slug>/...), or null. Unverified here: the API route
47	 *  checks it against the session before acting on it. */
48	function refererWorkspaceSlug(req: NextRequest): string | null {
49	  const referer = req.headers.get("referer");
50	  if (!referer) return null;
51	  let url: URL;
52	  try {
53	    url = new URL(referer);
54	  } catch {
55	    return null;
56	  }
57	  if (url.origin !== req.nextUrl.origin) return null;
58	  const m = url.pathname.match(/^\/client\/([a-z0-9-]+)(?:\/|$)/);
59	  return m ? m[1] : null;
60	}
61	
62	export async function proxy(req: NextRequest) {
63	  const raw = req.nextUrl.pathname;
64	
65	  // Per-tenant reference docs are served as static files under public/client-docs.
66	  // Next/Vercel's static resolver percent-DECODES the URL before mapping it to a
67	  // file, but req.nextUrl.pathname is NOT decoded - so a raw string match here
68	  // would miss an encoded path (e.g. /client-docs/%6eomadik/x.html) and let it
69	  // fall through to the static file undecoded. Decode fully (looping is safe -
70	  // over-decoding only ever gates MORE) and lowercase to fold case, then gate on
71	  // BOTH the decoded and raw prefixes so nothing under a gated prefix can slip
72	  // past.
73	  //
74	  // Decode leniently, one %XX token at a time, rather than with a single
75	  // decodeURIComponent(dec) call: that built-in throws on the WHOLE string if
76	  // ANY token in it is malformed, which would let one bad byte anywhere in the
77	  // path (e.g. a trailing %zz) hide a perfectly valid /%6eomadik/ earlier in
78	  // the same path from this decoder while Vercel's resolver may still tolerate
79	  // it. Decoding token-by-token means a malformed token just stays literal
80	  // instead of aborting the whole decode.
81	  const lenientDecodeOnce = (s: string) =>
82	    s.replace(/%[0-9A-Fa-f]{2}/g, (tok) => {
83	      try {
84	        return decodeURIComponent(tok);
85	      } catch {
86	        return tok;
87	      }
88	    });
89	  let dec = raw;
90	  for (let i = 0; i < 5; i++) {
91	    const d = lenientDecodeOnce(dec);
92	    if (d === dec) break;
93	    dec = d;
94	  }
95	  // Also fold backslashes to "/" (an encoded %5C decodes to "\", which some
96	  // static resolvers treat as a separator) and collapse "." / ".." segments, so a
97	  // traversal or separator-variant the resolver would normalise INTO a gated file
98	  // (e.g. /api/client/..%2f..%2fclient-docs%2fnomadik%2freference.html)
99	  // can't dodge the prefix test or slip through the /api allowlist. We then gate
100	  // on the raw, the token-decoded, and this normalised form - the union covers
101	  // every path that resolves under a gated namespace.
102	  const collapse = (path: string): string => {
103	    const out: string[] = [];
104	    for (const seg of path.split("/")) {
105	      if (seg === "..") out.pop();
106	      else if (seg !== "." && seg !== "") out.push(seg);
107	    }
108	    return "/" + out.join("/");
109	  };
110	  const p = collapse(dec.replace(/\\/g, "/")).toLowerCase();
111	  const rawLower = raw.toLowerCase();
112	
113	  const underNomadik =
114	    p === "/nomadik" ||
115	    p.startsWith("/nomadik/") ||
116	    rawLower === "/nomadik" ||
117	    rawLower.startsWith("/nomadik/");
118	  const underHandymancf =
119	    p === "/handymanclonakilty" ||
120	    p.startsWith("/handymanclonakilty/") ||
121	    rawLower === "/handymanclonakilty" ||
122	    rawLower.startsWith("/handymanclonakilty/");
123	  const underClient =
124	    p === "/client" ||
125	    p.startsWith("/client/") ||
126	    rawLower === "/client" ||
127	    rawLower.startsWith("/client/");
128	  // Owner-only admin surface. Nested under /client so it must be tested BEFORE
129	  // the tenant gate - a tenant session must never open it, and its own cookie
130	  // (method 'owner') never opens a tenant's pages.
131	  const underAdmin =
132	    p === "/client/admin" ||
133	    p.startsWith("/client/admin/") ||
134	    rawLower === "/client/admin" ||
135	    rawLower.startsWith("/client/admin/");
136	  const underLab =
137	    p === "/lab" ||
138	    p.startsWith("/lab/") ||
139	    rawLower === "/lab" ||
140	    rawLower.startsWith("/lab/");
141	  // /internal - owner-only personal tooling pages (currently just the
142	  // email-ingest automation's hosted summaries). Same owner cookie as /lab.
143	  const underInternal =
144	    p === "/internal" ||
145	    p.startsWith("/internal/") ||
146	    rawLower === "/internal" ||
147	    rawLower.startsWith("/internal/");
148	  // The login pages and auth endpoints stay public (a viewer must be able to
149	  // reach them without a session), and bypass the site-wide gate so sign-in
150	  // works even while the rest of the site is in pre-launch lockdown.
151	  // /api/internal/ is included here, NOT because it's public, but because it
152	  // authenticates itself with a bearer token (lib/internal-ingest/auth.ts) -
153	  // the email-ingest poller is a headless script with no browser cookie.
154	  const isAuthEndpoint =
155	    p === "/client/login" ||
156	    p.startsWith("/api/client/") ||
157	    p === "/client/admin/login" ||
158	    p.startsWith("/api/admin/") ||
159	    p.startsWith("/api/internal/");
160	
161	  // --- Gate 1 (retired namespaces): both legacy docs now live in the /client
162	  // portal. Permanent redirects so old bookmarks land on the portal login
163	  // pre-filled with the workspace. ---
164	  if (underNomadik) {
165	    return NextResponse.redirect(new URL("/client/login?c=nomadik", req.url), 308);
166	  }
167	  if (underHandymancf) {
168	    return NextResponse.redirect(new URL("/client/login?c=handymanclonakilty", req.url), 308);
169	  }
170	  // --- Gate 1.5: /client/admin (owner only; deny-by-default for the namespace).
171	  // Checked before the tenant gate: a valid tenant session must NOT satisfy
172	  // this gate, so it verifies the owner cookie exclusively. ---
173	  if (underAdmin && !isAuthEndpoint) {
174	    const cookie = req.cookies.get(ADMIN_COOKIE)?.value;
175	    const ok = cookie ? await verifyAdminSessionEdge(cookie) : false;
176	    if (!ok) return NextResponse.redirect(new URL("/client/admin/login", req.url));
177	    return NextResponse.next();
178	  }
179	  // --- Gate 1.6: /lab (owner only). Design prototypes, never customer-facing.
180	  // Deliberately the OWNER cookie and not the tenant one: a client has no
181	  // reason to reach an internal prototype, and one of these pages names a
182	  // product that has not launched. Bypassed under `next dev` so the board
183	  // compositor script keeps working against a local server. ---
184	  if (underLab && process.env.NODE_ENV !== "development") {
185	    const cookie = req.cookies.get(ADMIN_COOKIE)?.value;
186	    const ok = cookie ? await verifyAdminSessionEdge(cookie) : false;
187	    if (!ok) return NextResponse.redirect(new URL("/client/admin/login", req.url));
188	    return NextResponse.next();
189	  }
190	  // --- Gate 1.7: /internal (owner only, e.g. /internal/ingest). Same cookie
191	  // and login redirect as /lab - a second personal-tooling namespace under the
192	  // one existing owner session rather than a new auth mechanism. ---
193	  if (underInternal && !isAuthEndpoint) {
194	    const cookie = req.cookies.get(ADMIN_COOKIE)?.value;
195	    const ok = cookie ? await verifyAdminSessionEdge(cookie) : false;
196	    if (!ok) return NextResponse.redirect(new URL("/client/admin/login", req.url));
197	    return NextResponse.next();
198	  }
199	  // --- Gate 2: /client portal (multi-tenant; deny-by-default for the namespace) ---
200	  if (underClient && !isAuthEndpoint) {
201	    const cookie = req.cookies.get(CLIENT_COOKIE)?.value;
202	    const session = cookie ? await verifyClientSessionEdge(cookie) : null;
203	    if (!session) return NextResponse.redirect(new URL("/client/login", req.url));
204	
205	    // /client/<slug>/... names a workspace explicitly - a multi-workspace
206	    // session may open any slug it was granted, not only its primary one.
207	    // Bare /client (no slug segment) has nothing to check here; ClientIndex
208	    // resolves it to the primary slug itself. An ungranted slug bounces to
209	    // the primary rather than denying outright, matching the old behaviour
210	    // of a single-workspace session hitting a foreign slug.
211	    const urlSlugMatch = p.match(/^\/client\/([a-z0-9-]+)/);
212	    const urlSlug = urlSlugMatch ? urlSlugMatch[1] : null;
213	    if (urlSlug && !sessionGrantsSlug(session, urlSlug)) {
214	      return NextResponse.redirect(new URL(`/client/${session.slug}`, req.url));
215	    }
216	
217	    const headers = new Headers(req.headers);
218	    if (urlSlug) headers.set(PORTAL_ACTIVE_SLUG_HEADER, urlSlug);
219	    else headers.delete(PORTAL_ACTIVE_SLUG_HEADER);
220	    return NextResponse.next({ request: { headers } });
221	  }
222	  // --- Gate 2b: /client-docs/<slug>/* (per-tenant static reference docs) ---
223	  // A client may only reach a slug their session was granted, so client A can
224	  // never fetch client B's doc.
225	  const docMatch = p.match(/^\/client-docs\/([a-z0-9-]+)(?:\/|$)/);
226	  if (docMatch) {
227	    const docSlug = docMatch[1];
228	    const cookie = req.cookies.get(CLIENT_COOKIE)?.value;
229	    const session = cookie ? await verifyClientSessionEdge(cookie) : null;
230	    if (!session || !sessionGrantsSlug(session, docSlug)) {
231	      return NextResponse.redirect(new URL("/client/login", req.url));
232	    }
233	    return NextResponse.next();
234	  }
235	  // /api/client/* has no workspace in its own URL, so the active one is the
236	  // portal page that issued the request: the same-origin Referer's
237	  // /client/<slug>. Any client-sent copy of the header is dropped first, so the
238	  // header only ever carries what the proxy derived. The route re-checks it
239	  // against the session (lib/portal-editor/auth.ts); a multi-workspace session
240	  // with no header is refused there, not defaulted to its primary.
241	  if (p.startsWith("/api/client/")) {
242	    const headers = new Headers(req.headers);
243	    headers.delete(PORTAL_ACTIVE_SLUG_HEADER);
244	    const activeSlug = refererWorkspaceSlug(req);
245	    if (activeSlug) headers.set(PORTAL_ACTIVE_SLUG_HEADER, activeSlug);
246	    return NextResponse.next({ request: { headers } });
247	  }
248	  if (isAuthEndpoint) {
249	    return NextResponse.next();
250	  }
251	
252	  // --- Offline surfaces: a route that exists in the repo but not on the site ---
253	  // Checked here rather than with notFound() in the page, so /research/anything
254	  // and any sub-path 404 together. A 404 rather than a redirect: "removed while
255	  // I develop it" means a visitor finds nothing, and a redirect would advertise
256	  // that the route is there. See lib/flags.ts.
257	  // Gates on the normalised path AND the raw one, same belt-and-braces as the
258	  // tenant prefixes above: an encoded or separator-variant path must not dodge
259	  // this any more than it dodges those.
260	  const under = (prefix: string) => (s: string) =>
261	    s === prefix || s.startsWith(prefix + "/");
262	  const offline: Array<(s: string) => boolean> = [];
263	  if (!RESEARCH_LIVE) offline.push(under("/research"));
264	  if (!CONSULTING_LIVE) offline.push(under("/services/consulting"));
265	  if (offline.some((f) => f(p) || f(rawLower))) {
266	    // REWRITE, not an empty body (2026-09-06, stage 1 of the landing
267	    // reassessment). `new NextResponse(null, { status: 404 })` sent a zero-byte
268	    // 404, so a visitor following a stale link to /services/consulting got the
269	    // browser's own error page: no header, no footer, no way back into the
270	    // site, and nothing saying whose site she had reached. Rewriting to a path
271	    // that cannot exist makes Next render app/not-found.tsx, which is branded
272	    // and links home, while the status stays 404 so crawlers read it the same
273	    // way as before.
274	    return NextResponse.rewrite(new URL("/_offline", req.url), { status: 404 });
275	  }
276	
277	  // --- Gate 4: site-wide pre-launch ---
278	  const password = process.env.SITE_GATE_PASSWORD;
279	  if (!password) return NextResponse.next(); // gate off
280	
281	  const user = process.env.SITE_GATE_USER || "solaisoft";
282	  const header = req.headers.get("authorization") || "";
283	
284	  if (header.startsWith("Basic ")) {
285	    try {
286	      const decoded = atob(header.slice(6));
287	      const sep = decoded.indexOf(":");
288	      const u = decoded.slice(0, sep);
289	      const pw = decoded.slice(sep + 1);
290	      if (u === user && pw === password) return NextResponse.next();
291	    } catch {
292	      // fall through to challenge
293	    }
294	  }
295	
296	  return new NextResponse("Authentication required.", {
297	    status: 401,
298	    headers: {
299	      "WWW-Authenticate": 'Basic realm="Solaisoft preview", charset="UTF-8"',
300	      "Cache-Control": "no-store",
301	    },
302	  });
303	}
304	
305	export const config = {
306	  // Gate everything except Next internals, the favicon, and the public brand
307	  // logo (linked from the email signature, so it must load without the gate).
308	  matcher: ["/((?!_next/static|_next/image|favicon.ico|solaisoft-logo-coral.png).*)"],
309	};
